import{_ as a,c as o,o as t,ag as l}from"./chunks/framework.B-XtCDNB.js";const p=JSON.parse('{"title":"3.4. Semantic Analyzer","description":"3.4. Semantic Analyzer Vala.SemanticAnalyzer is a CodeVisitor that looks up the symbols that have been, parsed and checks if the symbols are being used correctly. This includes: Verifying that for...","frontmatter":{"prev":{"text":"3.3. Symbol Resolution","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-03-symbol-resolution"},"next":{"text":"3.5. Flow Analyzer","link":"/guides/compiler-guide/03-00-the-vala-compiler/03-05-flow-analyzer"}},"headers":[],"relativePath":"guides/compiler-guide/03-00-the-vala-compiler/03-04-semantic-analyzer.md","filePath":"guides/compiler-guide/03-00-the-vala-compiler/03-04-semantic-analyzer.md","lastUpdated":1785795526000}'),i={name:"guides/compiler-guide/03-00-the-vala-compiler/03-04-semantic-analyzer.md"};function n(c,e,r,s,d,h){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-4-semantic-analyzer" tabindex="-1">3.4. Semantic Analyzer <a class="header-anchor" href="#_3-4-semantic-analyzer" aria-label="Permalink to &quot;3.4. Semantic Analyzer&quot;">​</a></h1><p><code>Vala.SemanticAnalyzer</code> is a <code>CodeVisitor</code> that looks up the symbols that have been, parsed and checks if the symbols are being used correctly.</p><p>This includes:</p><ul><li>Verifying that for each symbol type, the syntax is being followed</li><li>The rules of how each symbol can be used is being followed</li></ul><p>The key method to look at is <code>Vala.SemanticAnalyzer.analyze ()</code></p><h2 id="_3-4-1-how-the-built-in-symbol-types-are-looked-up" tabindex="-1">3.4.1 How The Built-in Symbol Types Are Looked Up <a class="header-anchor" href="#_3-4-1-how-the-built-in-symbol-types-are-looked-up" aria-label="Permalink to &quot;3.4.1 How The Built-in Symbol Types Are Looked Up&quot;">​</a></h2><p>Initially symbol types are looked up from the <code>Vala.CodeContext</code> <code>root</code> (<code>Vala.Namespace</code>).</p><p>In <code>Vala.Compiler</code> for the <code>run()</code> method, for each source filename given to the compiler, the <code>Vala.CodeContext.add_source_file_name ()</code> is called (unless the compiler is run with the Fast VAPIs feature enabled).</p><p>On each call to the <code>add_source_file_name ()</code> method on <code>Vala.CodeContext</code>, a default namespace <code>using</code> directive is added to the <code>Vala.SourceFile</code> object representing each source file.</p><p>The default namespace that gets added depends on the <code>profile</code> option set when the compiler is executed:</p><ul><li><code>gobject</code> (default): <code>using GLib;</code></li><li><code>posix</code>: <code>using Posix;</code></li></ul><p>This provides the implementation of the built-in types of the language.</p><p>The implementation of each type are then added to the namespace scope which is then looked up when the <code>Vala.SemanticAnalyzer.analyze()</code> method is called.</p><h2 id="_3-4-2-how-each-symbol-in-the-symbol-tree-is-checked" tabindex="-1">3.4.2 How Each Symbol in the Symbol Tree Is Checked <a class="header-anchor" href="#_3-4-2-how-each-symbol-in-the-symbol-tree-is-checked" aria-label="Permalink to &quot;3.4.2 How Each Symbol in the Symbol Tree Is Checked&quot;">​</a></h2><p>After looking up the built-in symbol types, in <code>Vala.SemanticAnalyzer.analyze ()</code>, the method then continues on by calling <code>Vala.CodeNode.check ()</code> on the namespaces in the code context root.</p><p>After, <code>CodeContext.accept ()</code> is called with the semantic instance and the code visitor recursively goes through the entire symbol tree to ensure that all the symbols are being used correctly.</p><p>Also, <code>Vala.SemanticAnalyzer</code> contains methods and static functions that are used as shared reusable logic across the symbol tree of ensuring that symbol&#39;s are being used correctly. For example <code>Vala.SemanticAnalyzer.check_arguments ()</code> checks the arguments of an expression, ensuring that the correct amount of arguments are being used.</p><h2 id="_3-4-3-error-handling" tabindex="-1">3.4.3 Error Handling <a class="header-anchor" href="#_3-4-3-error-handling" aria-label="Permalink to &quot;3.4.3 Error Handling&quot;">​</a></h2><p>If while checking the symbols, any errors have been reported, after the semantic analyzer has finishing checking through the entire symbol tree, the compiler program will exit early instead of proceeding with the Flow Analyzer.</p>',19)])])}const u=a(i,[["render",n]]);export{p as __pageData,u as default};
